<?php require __DIR__.'/includes/bootstrap.php';$slug=trim($_GET['slug']??'');$error='';$message='';$article=null;if($pdo&&$slug){$s=$pdo->prepare("SELECT id,title FROM articles WHERE slug=? AND status='published'");$s->execute([$slug]);$article=$s->fetch();}if(!$article){http_response_code(404);exit('Article not found');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$body=trim($_POST['body']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$body===''||strlen($body)>5000)$error='Complete all fields with a valid email and a message under 5,000 characters.';else{$q=$pdo->prepare("INSERT INTO comments(article_id,name,email,body,status) VALUES(?,?,?,?, 'pending')");$q->execute([$article['id'],$name,$email,$body]);$message='Your comment is awaiting moderation.';}}$title='Comment';require __DIR__.'/includes/header.php';?><div class="container"><section class="card"><h1>Comment on <?=e($article['title'])?></h1><?php if($error):?><p role="alert"><?=e($error)?></p><?php endif;?><?php if($message):?><p role="status"><?=e($message)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><p><label>Name<input name="name" required maxlength="120"></label></p><p><label>Email<input type="email" name="email" required maxlength="190"></label></p><p><label>Comment<textarea name="body" rows="6" required maxlength="5000"></textarea></label></p><button>Submit comment</button></form></section></div><?php require __DIR__.'/includes/footer.php';
